"use client";

import type { CSSProperties, ReactNode } from "react";
import { interpolate, useCurrentFrame } from "remotion";

export type BeforeAfterOrientation = "horizontal" | "vertical";

export interface BeforeAfterLabels {
  before: string;
  after: string;
}

export interface BeforeAfterProps {
  /** Outgoing scene under the divider. Falls back to a legacy-spreadsheet mock. */
  before?: ReactNode;
  /** Incoming scene revealed by the sweep. Falls back to a clean Acme dashboard. */
  after?: ReactNode;
  /** Sweep left→right (horizontal) or top→bottom (vertical). */
  orientation?: BeforeAfterOrientation;
  /** Frame at which the divider starts moving. */
  sweepStart?: number;
  /** Length of the main ease-out sweep, in frames (a brief settle drift follows). */
  sweepDuration?: number;
  /** Final divider position 0..1. Values below 1 hold the comparison mid-sweep. */
  sweepTo?: number;
  /** Chip texts. Empty strings hide a chip. */
  labels?: BeforeAfterLabels;
  /** Flat alias for `labels.before` (used by the customizer). */
  beforeLabel?: string;
  /** Flat alias for `labels.after` (used by the customizer). */
  afterLabel?: string;
  /** Show the circular knob on the divider. */
  handle?: boolean;
  /** Divider bar color. */
  dividerColor?: string;
  /** Knob fill color. */
  handleColor?: string;
  /** Width of the comparison frame, in px. */
  width?: number;
  /** Height of the comparison frame, in px. */
  height?: number;
  /** Global playback multiplier. */
  speed?: number;
  className?: string;
}

const FONT_FAMILY =
  'Inter, var(--font-geist-sans), -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';

/** Extra travel appended after the main sweep — the "settle drift". */
export const SETTLE_DRIFT = 0.035;

/** Frames the settle drift takes after the main sweep ends. */
export const DRIFT_FRAMES = 12;

/** Clamp to [0, 1]. */
export function clamp01(v: number): number {
  return Math.min(1, Math.max(0, v));
}

/** Fast, subtle ease-out (cubic). */
export function easeOutCubic(t: number): number {
  const c = clamp01(t);
  return 1 - (1 - c) ** 3;
}

/** Smoothstep — zero velocity at both ends, used for the settle drift. */
export function smoothstep(t: number): number {
  const c = clamp01(t);
  return c * c * (3 - 2 * c);
}

export interface SweepOptions {
  sweepStart: number;
  sweepDuration: number;
  /** Final divider position 0..1. */
  sweepTo: number;
}

/**
 * Pure divider-position schedule: 0 until `sweepStart`, an ease-out sweep to
 * just short of `sweepTo` over `sweepDuration`, then a brief slow drift that
 * settles on `sweepTo` over `DRIFT_FRAMES`. Holds there forever after, so the
 * comparison can rest mid-sweep when `sweepTo < 1`.
 */
export function sweepProgress(frame: number, options: SweepOptions): number {
  const { sweepStart, sweepDuration, sweepTo } = options;
  const target = clamp01(sweepTo);
  if (target <= 0) return 0;
  const drift = Math.min(SETTLE_DRIFT, target * 0.08);
  const mainTarget = target - drift;
  if (frame <= sweepStart) return 0;
  if (frame < sweepStart + sweepDuration) {
    return easeOutCubic((frame - sweepStart) / sweepDuration) * mainTarget;
  }
  const d = (frame - sweepStart - sweepDuration) / DRIFT_FRAMES;
  return mainTarget + smoothstep(d) * drift;
}

/**
 * CSS clip-path inset revealing the leading `progress` fraction of the
 * after-layer: from the left (horizontal) or the top (vertical).
 */
export function clipInset(
  progress: number,
  orientation: BeforeAfterOrientation,
): string {
  const rest = (1 - clamp01(progress)) * 100;
  return orientation === "horizontal"
    ? `inset(0 ${rest}% 0 0)`
    : `inset(0 0 ${rest}% 0)`;
}

/**
 * Chip visibility for a given divider position: the After chip fades in as
 * soon as the sweep uncovers a sliver, the Before chip fades out only when
 * the before-region is nearly gone.
 */
export function chipOpacities(progress: number): {
  before: number;
  after: number;
} {
  const p = clamp01(progress);
  return {
    before: 1 - clamp01((p - 0.9) / 0.08),
    after: clamp01((p - 0.03) / 0.12),
  };
}

