const DASH_BARS = [42, 58, 50, 66, 74, 62, 84, 96];

const DASH_MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug"];

/** Clean Acme dashboard used when `after` is not provided. */
