/* ------------------------------------------------------------------ */
/* Component                                                           */
/* ------------------------------------------------------------------ */

function Chip({ text, style }: { text: string; style: CSSProperties }) {
  return (
    <div
      style={{
        position: "absolute",
        background: "#FFFFFF",
        border: "1px solid #E4E7EC",
        borderRadius: 6,
        color: "#667085",
        fontSize: 13,
        fontWeight: 600,
        letterSpacing: "-0.01em",
        padding: "4px 10px",
        fontFamily: FONT_FAMILY,
        boxShadow: "0 2px 8px rgba(16,24,40,0.06)",
        ...style,
      }}
    >
      {text}
    </div>
  );
}

export function BeforeAfter({
  before,
  after,
  orientation = "horizontal",
  sweepStart = 15,
  sweepDuration = 30,
  sweepTo = 1,
  labels,
  beforeLabel = "Before",
  afterLabel = "After",
  handle = true,
  dividerColor = "#FFFFFF",
  handleColor = "#266DF0",
  width = 960,
  height = 560,
  speed = 1,
  className,
}: BeforeAfterProps) {
  const frame = useCurrentFrame() * speed;

  const chipLabels: BeforeAfterLabels = labels ?? {
    before: beforeLabel,
    after: afterLabel,
  };

  const progress = sweepProgress(frame, { sweepStart, sweepDuration, sweepTo });
  const horizontal = orientation === "horizontal";
  const chips = chipOpacities(progress);

  const beforeContent = before ?? <LegacySpreadsheet />;
  const afterContent = after ?? <AcmeDashboard />;

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <div
        style={{
          position: "relative",
          width,
          height,
          borderRadius: 10,
          overflow: "hidden",
          border: "1px solid #E4E7EC",
          boxShadow: "0 16px 40px rgba(16,24,40,0.08)",
          // Quick fade-up entrance; no bounce.
          opacity: interpolate(frame, [0, 10], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          }),
        }}
      >
        {/* Before layer (full-bleed underneath) */}
        <div style={{ position: "absolute", inset: 0 }}>{beforeContent}</div>

        {/* After layer, clipped to the swept region */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            clipPath: clipInset(progress, orientation),
            willChange: "clip-path",
          }}
        >
          {afterContent}
        </div>

        {/* Label chips */}
        {chipLabels.after ? (
          <Chip
            text={chipLabels.after}
            style={{ top: 14, left: 14, opacity: chips.after }}
          />
        ) : null}
        {chipLabels.before ? (
          <Chip
            text={chipLabels.before}
            style={
              horizontal
                ? { top: 14, right: 14, opacity: chips.before }
                : { bottom: 14, right: 14, opacity: chips.before }
            }
          />
        ) : null}

        {/* Divider + handle knob */}
        <div
          style={{
            position: "absolute",
            top: horizontal ? 0 : `${progress * 100}%`,
            left: horizontal ? `${progress * 100}%` : 0,
            width: horizontal ? 2 : "100%",
            height: horizontal ? "100%" : 2,
            translate: horizontal ? "-1px 0px" : "0px -1px",
            background: dividerColor,
            boxShadow: "0 0 14px rgba(16,24,40,0.35)",
            // Slide off cleanly when the sweep completes a full reveal.
            opacity: 1 - clamp01((progress - 0.96) / 0.04),
          }}
        >
          {handle ? (
            <div
              style={{
                position: "absolute",
                top: "50%",
                left: "50%",
                translate: "-50% -50%",
                width: 44,
                height: 44,
                borderRadius: 22,
                background: handleColor,
                border: `2px solid ${dividerColor}`,
                boxShadow: "0 4px 14px rgba(16,24,40,0.3)",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                rotate: horizontal ? "0deg" : "90deg",
              }}
            >
              <svg
                width={22}
                height={12}
                viewBox="0 0 22 12"
                fill="none"
                aria-hidden
              >
                <path
                  d="M6.5 1L1.5 6L6.5 11"
                  stroke="#FFFFFF"
                  strokeWidth={2}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
                <path
                  d="M15.5 1L20.5 6L15.5 11"
                  stroke="#FFFFFF"
                  strokeWidth={2}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
            </div>
          ) : null}
        </div>
      </div>
    </div>
  );
}
